namespace Atc.XamlToolkit.SourceGenerators.Tests.Generators;

[SuppressMessage("Design", "MA0048:File name must match type name", Justification = "OK.")]
public sealed partial class ViewModelGeneratorTests
{
    [Fact]
    public void INotifyPropertyChanged_OnPlainClass_GeneratesScaffolding()
    {
        const string inputCode =
            """
            namespace TestNamespace;

            [INotifyPropertyChanged]
            public partial class Customer
            {
            }
            """;

        const string expectedCode =
            """
            // <auto-generated>
            #nullable enable
            using System.Collections.Generic;
            using System.ComponentModel;
            using System.Runtime.CompilerServices;

            namespace TestNamespace;

            public partial class Customer : INotifyPropertyChanged
            {
                public event PropertyChangedEventHandler? PropertyChanged;

                protected void RaisePropertyChanged([CallerMemberName] string? propertyName = null)
                    => PropertyChanged?.Invoke(this, Atc.XamlToolkit.Mvvm.PropertyChangedEventArgsCache.Get(propertyName));

                protected void OnPropertyChanged([CallerMemberName] string? propertyName = null)
                    => RaisePropertyChanged(propertyName);

                protected bool Set<T>(ref T field, T newValue, [CallerMemberName] string? propertyName = null)
                {
                    if (EqualityComparer<T>.Default.Equals(field, newValue))
                    {
                        return false;
                    }

                    field = newValue;
                    RaisePropertyChanged(propertyName);
                    return true;
                }
            }

            #nullable disable
            """;

        var generatorResult = RunGenerator<ViewModelGenerator>(inputCode);

        AssertGeneratorRunResultAsEqual(expectedCode, generatorResult);
    }

    [Fact]
    public void INotifyPropertyChanged_CombinedWithObservableProperty_GeneratesBothFiles()
    {
        // The two pipelines (INPC scaffolding and ObservableProperty setter) emit
        // separate generated files that combine into one partial class. Verify
        // both files are produced and that the ObservableProperty setter calls
        // RaisePropertyChanged — which now resolves against the INPC scaffolding
        // instead of requiring : ObservableObject inheritance.
        const string inputCode =
            """
            namespace TestNamespace;

            [INotifyPropertyChanged]
            public partial class Customer
            {
                [ObservableProperty]
                private string name;
            }
            """;

        var generatorResult = RunGenerator<ViewModelGenerator>(inputCode);

        generatorResult.GeneratorResult.GeneratedSources.Length
            .Should()
            .Be(2, "one file per generator pipeline (INPC scaffolding + ObservableProperty)");

        var combined = string.Concat(
            generatorResult.GeneratorResult.GeneratedSources
                .Select(s => s.SourceText.ToString()));

        combined.Should().Contain("public event PropertyChangedEventHandler? PropertyChanged;");
        combined.Should().Contain("protected void RaisePropertyChanged");
        combined.Should().Contain("public string Name");
        combined.Should().Contain("RaisePropertyChanged(nameof(Name));");
    }

    [Fact]
    [SuppressMessage("Usage", "xUnit1051:Calls to methods which accept CancellationToken should use TestContext.Current.CancellationToken", Justification = "Compilation/generator APIs take their own optional cancellation token; the test does not need to plumb the framework token here.")]
    public void INotifyPropertyChanged_CombinedWithObservableProperty_CompilesCleanly()
    {
        // Snapshot tests pin output text but don't catch issues like a missing
        // using or a name-resolution failure. Drive the generator directly,
        // then check the resulting compilation has no error diagnostics — this
        // is the only check that the two pipelines produce code that actually
        // compiles together.
        const string inputCode =
            """
            namespace TestNamespace;

            [Atc.XamlToolkit.Mvvm.INotifyPropertyChanged]
            public partial class Customer
            {
                [Atc.XamlToolkit.Mvvm.ObservableProperty]
                private string firstName = string.Empty;

                [Atc.XamlToolkit.Mvvm.ObservableProperty]
                private string lastName = string.Empty;
            }
            """;

        // Force-load the runtime library so Atc.XamlToolkit.Mvvm.* types
        // appear in the test AppDomain and are usable as metadata references.
        System.Reflection.Assembly.Load("Atc.XamlToolkit");

        var inputCompilation = CSharpCompilation.Create(
            "compilation",
            [CSharpSyntaxTree.ParseText(inputCode)],
            AppDomain.CurrentDomain
                .GetAssemblies()
                .Where(a => !a.IsDynamic)
                .Select(a => MetadataReference.CreateFromFile(a.Location))
                .ToArray<MetadataReference>(),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var generator = new ViewModelGenerator();
        GeneratorDriver driver = CSharpGeneratorDriver.Create(generator);

        _ = driver.RunGeneratorsAndUpdateCompilation(
            inputCompilation,
            out var outputCompilation,
            out _);

        var errors = outputCompilation.GetDiagnostics()
            .Where(d => d.Severity == DiagnosticSeverity.Error)
            .ToList();

        errors.Should()
            .BeEmpty(
                "the combined output of [INotifyPropertyChanged] + [ObservableProperty] must compile cleanly. Errors: {0}",
                string.Join(Environment.NewLine, errors.Select(e => e.ToString())));
    }

    [Fact]
    public void INotifyPropertyChanged_OnNonPartialClass_EmitsMissingPartialDiagnostic()
    {
        const string inputCode =
            """
            namespace TestNamespace;

            [INotifyPropertyChanged]
            public class Customer
            {
            }
            """;

        var generatorResult = RunGenerator<ViewModelGenerator>(inputCode);

        AssertGeneratorRunResultHasDiagnostics(["AtcXamlToolkit0002"], generatorResult);
    }
}